import*as Common from"../../../../core/common/common.js";import*as Platform from"../../../../core/platform/platform.js";const roundAndStringify=o=>o.map((o=>Platform.StringUtilities.stringifyWithPrecision(o,2))),functionParamsText=o=>`${o[0]} ${o[1]} ${o[2]} / ${o[3]}`;export const colorFormatSpec={rgb:{label:"RGBA",toValues:function(o){return roundAndStringify(o.as("rgba").canonicalRGBA())},fromValues:function(o){return Common.Color.parse(`rgb(${functionParamsText(o)})`)}},hsl:{label:"HSLA",toValues:function(o){const n=roundAndStringify(o.as("hsla").canonicalHSLA());return n[1]=n[1]+"%",n[2]=n[2]+"%",n},fromValues:function(o){return Common.Color.parse(`hsl(${functionParamsText(o)})`)}},hwb:{label:"HWBA",toValues:function(o){const n=roundAndStringify(o.as("hwba").canonicalHWBA());return n[1]=n[1]+"%",n[2]=n[2]+"%",n},fromValues:function(o){return Common.Color.parse(`hwb(${functionParamsText(o)})`)}},lch:{label:"lchA",toValues:function(o){const n=o.as("lch");return roundAndStringify([n.l,n.c,n.h,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`lch(${functionParamsText(o)})`)}},oklch:{label:"lchA",toValues:function(o){const n=o.as("oklch");return roundAndStringify([n.l,n.c,n.h,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`oklch(${functionParamsText(o)})`)}},lab:{label:"labA",toValues:function(o){const n=o.as("lab");return roundAndStringify([n.l,n.a,n.b,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`lab(${functionParamsText(o)})`)}},oklab:{label:"labA",toValues:function(o){const n=o.as("oklab");return roundAndStringify([n.l,n.a,n.b,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`oklab(${functionParamsText(o)})`)}},srgb:{label:"RGBA",toValues:function(o){const n=o.as("srgb");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(srgb ${functionParamsText(o)})`)}},"srgb-linear":{label:"RGBA",toValues:function(o){const n=o.as("srgb-linear");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(srgb-linear ${functionParamsText(o)})`)}},"display-p3":{label:"RGBA",toValues(o){const n=o.as("display-p3");return roundAndStringify([n.p0,n.p1,n.p2,1])},fromValues:o=>Common.Color.parse(`color(display-p3 ${functionParamsText(o)})`)},"a98-rgb":{label:"RGBA",toValues:function(o){const n=o.as("a98-rgb");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(a98-rgb ${functionParamsText(o)})`)}},"prophoto-rgb":{label:"RGBA",toValues:function(o){const n=o.as("prophoto-rgb");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(prophoto-rgb ${functionParamsText(o)})`)}},rec2020:{label:"RGBA",toValues:function(o){const n=o.as("rec2020");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(rec2020 ${functionParamsText(o)})`)}},xyz:{label:"xyzA",toValues:function(o){const n=o.as("xyz");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(xyz ${functionParamsText(o)})`)}},"xyz-d50":{label:"xyzA",toValues:function(o){const n=o.as("xyz-d50");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(xyz-d50 ${functionParamsText(o)})`)}},"xyz-d65":{label:"xyzA",toValues:function(o){const n=o.as("xyz-d65");return roundAndStringify([n.p0,n.p1,n.p2,n.alpha??1])},fromValues:function(o){return Common.Color.parse(`color(xyz-d65 ${functionParamsText(o)})`)}}};